<?php require 'config.php';require_admin();verify_csrf();$d=read_json('delivery.json',[]);if($_SERVER['REQUEST_METHOD']==='POST'){$d['default_fee']=(float)$_POST['default_fee'];$d['free_after']=(float)$_POST['free_after'];$d['zones']=[];foreach($_POST['zone_name']??[] as $i=>$n)if(trim($n)!=='')$d['zones'][]=['id'=>uid('Z'),'name'=>trim($n),'fee'=>(float)($_POST['zone_fee'][$i]??0)];write_json('delivery.json',$d);flash('تم حفظ إعدادات التوصيل.');redirect('delivery.php');}$title='التوصيل';require 'header.php';?><div class="form"><h1>🚚 إعداد التوصيل</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="number" name="default_fee" value="<?=e((string)($d['default_fee']??0))?>" placeholder="السعر الافتراضي"><input type="number" name="free_after" value="<?=e((string)($d['free_after']??0))?>" placeholder="مجاني بعد قيمة (0 لتعطيل)"><?php foreach(($d['zones']??[]) as $z):?><div class="row"><input name="zone_name[]" value="<?=e($z['name'])?>"><input type="number" name="zone_fee[]" value="<?=e((string)$z['fee'])?>"></div><?php endforeach;?><div class="row"><input name="zone_name[]" placeholder="منطقة جديدة"><input type="number" name="zone_fee[]" placeholder="سعر التوصيل"></div><button class="btn">حفظ</button></form></div><?php require 'footer.php';?>